package wasm_test

import (
	"testing"

	"github.com/sei-protocol/sei-chain/sei-wasmd/x/wasm"
	"github.com/sei-protocol/sei-chain/sei-wasmd/x/wasm/types"
	"github.com/sei-protocol/sei-chain/testutil/configtest"
	"github.com/sei-protocol/sei-chain/testutil/fuzzing"
	"github.com/stretchr/testify/require"
)

// seid no longer generates a [wasm] section, so a newly generated node resolves every
// key here to the in-code defaults. Files generated by older seid versions still carry
// query_gas_limit = 300000, which matches the in-code default, and lru_size, which
// nothing reads.
//
// Two other read sites are worth naming: memory_cache_size is read but was never
// templated, so it is reachable only by hand-editing, and the global --trace flag
// doubles as the contract debug-mode switch, so enabling ABCI stack traces also turns
// on contract debugging.

// TestReadWasmConfigAbsentKeysKeepDefaults pins the section baseline — the in-code
// defaults, which is what a node with no [wasm] section resolves. Both sides move
// together when a default changes, so this asserts the reader's behavior rather
// than the values themselves.
func TestReadWasmConfigAbsentKeysKeepDefaults(t *testing.T) {
	cfg, err := wasm.ReadWasmConfig(configtest.AppOpts{})
	require.NoError(t, err, "an absent [wasm] section must read cleanly")
	require.Equal(t, types.DefaultWasmConfig(), cfg,
		"an absent [wasm] section must resolve to the declared defaults")
}

// TestQueryGasLimitInCodeDefault pins the smart-query gas allowance of every node whose
// app.toml has no [wasm] section, which includes every node seid now generates.
//
// The value is stated here rather than read back from DefaultWasmConfig, so moving it is a
// failure: it changes what contract queries succeed on those nodes. What a freshly
// generated home resolves end to end is pinned by
// TestGeneratedAppTOMLLeavesTheWasmQueryGasLimitToTheInCodeDefault in cmd/seid/cmd.
func TestQueryGasLimitInCodeDefault(t *testing.T) {
	const want = uint64(300_000)

	if inCode := types.DefaultWasmConfig().SmartQueryGasLimit; inCode != want {
		t.Fatalf("the in-code smart-query gas limit is now %d, was %d. Every node whose app.toml "+
			"lacks [wasm] runs smart queries with it, so record the new value deliberately",
			inCode, want)
	}
}

// TestLruSizeKeyIsInert records that lru_size, which app.toml files generated by
// older seid versions still carry, is read by nothing: ReadWasmConfig reads
// memory_cache_size, so editing lru_size has no effect on the cache.
func TestLruSizeKeyIsInert(t *testing.T) {
	cfg, err := wasm.ReadWasmConfig(configtest.AppOpts{"wasm.lru_size": uint32(512)})
	if err != nil {
		t.Fatalf("ReadWasmConfig: %v", err)
	}
	if cfg.MemoryCacheSize != types.DefaultWasmConfig().MemoryCacheSize {
		t.Fatalf("wasm.lru_size resolved into MemoryCacheSize (%d); the live key is "+
			"memory_cache_size, and if the two were unified that needs a migration",
			cfg.MemoryCacheSize)
	}
}

// FuzzWasmSimulationGasLimitIsInert records that simulation_gas_limit, which a hand-edited
// app.toml may still carry, is read by nothing. A value of any shape reads cleanly and
// leaves the config at its defaults, including a string that does not convert to a number,
// which used to fail the read and so the node's start.
func FuzzWasmSimulationGasLimitIsInert(f *testing.F) {
	f.Add(fuzzing.KindString, "500000", int64(0), false)
	f.Add(fuzzing.KindInt64, "", int64(500000), false)
	f.Add(fuzzing.KindString, "", int64(0), false)
	f.Add(fuzzing.KindString, "not-a-number", int64(0), false)
	f.Add(fuzzing.KindNil, "", int64(0), false)

	f.Fuzz(func(t *testing.T, kind uint8, s string, n int64, b bool) {
		value := fuzzing.ConfigValue(kind, s, n, b)
		cfg, err := wasm.ReadWasmConfig(configtest.AppOpts{"wasm.simulation_gas_limit": value})
		if err != nil {
			t.Fatalf("simulation_gas_limit = %#v must be ignored, got %v", value, err)
		}
		if cfg != types.DefaultWasmConfig() {
			t.Fatalf("simulation_gas_limit = %#v changed the wasm config to %+v", value, cfg)
		}
	})
}
